mapper.sql:
	FROM
		ELIB_COMMENT a, ELIB_BOOK b
	WHERE 1=1
	AND a.book_idx = b.book_idx

	AND b.type = #{type}


	AND	a.member_id LIKE '%'||#{member_id}||'%'


	AND b.parent_id = #{parent_id}


	AND b.cate_id = #{cate_id}


    AND TO_DATE(#{search_sdt}, 'yyyy-mm-dd') <= a.add_date


    AND a.add_date <= TO_DATE(#{search_edt} || ' 23:59:59', 'yyyy-mm-dd hh24:mi:ss')

mapper.select:
${pagingTop}
SELECT
	comment_idx, TO_CHAR(add_date, 'YYYY-MM-DD') AS add_date, book_idx, user_idx, member_id, user_comment

${pagingBottom}

mapper.insert:
INSERT INTO ELIB_COMMENT (
	comment_idx, add_date, book_idx, user_idx, member_id, user_comment
) VALUES (
	ELIB_COMMENT_SEQ.NEXTVAL, SYSDATE, #{book_idx}, #{user_idx}, #{member_id}, #{user_comment}
)

mapper.update:
UPDATE ELIB_COMMENT SET
	user_comment = #{user_comment}
WHERE
	comment_idx = #{comment_idx}
